backtest() replays history as it happened. To test a strategy on other sequences (windows of the history, or paths resampled from it), feed a Replay yourself. The bars still run through the C++ engine one at a time; in our measurements, feeding a sequence in blocks took no longer than one backtest() call over the same bars. Parallel runs belong in separate processes.
import numpy as np
import pandas as pd
import pyatl

rng = np.random.default_rng(11)
days = pd.bdate_range("2023-01-02", periods=500)
symbols = ["005930", "000660", "035420"]
returns = rng.normal(0, 0.012, (len(days), len(symbols)))
closes = np.round(30_000 * np.exp(np.cumsum(returns, axis=0)), -1)
data = {}
for i, s in enumerate(symbols):
    c = closes[:, i]
    data[s] = pd.DataFrame(
        {"open": c, "high": c, "low": c, "close": c, "volume": 1e6}, index=days
    )


class Reversal:
    """Each day, holds 1,000,000 KRW of the symbol that fell most."""

    def __init__(self):
        self.prev, self.held = {}, None

    def on_bars(self, ctx, bars):
        moves = []
        for bar in bars:
            if bar.symbol in self.prev:
                change = bar.close / self.prev[bar.symbol] - 1
                moves.append((change, bar.symbol, bar.close))
            self.prev[bar.symbol] = bar.close
        if not moves:
            return
        _, pick, price = min(moves)
        if self.held and self.held != pick:
            ctx.target(self.held, 0)
        ctx.target(pick, int(1_000_000 // price))
        self.held = pick

BacktestResult reports the library’s figures, and carries the fills and the equity curve as NumPy columns, so any other measure is computed from them.
import numpy as np
import pandas as pd
import pyatl

rng = np.random.default_rng(1)
days = pd.bdate_range("2024-01-02", periods=500)
close = np.round(20_000 * np.exp(np.cumsum(rng.normal(0.0002, 0.012, len(days)))), -1)
frame = pd.DataFrame(
    {"open": close, "high": close, "low": close, "close": close, "volume": 1e6}, index=days
)


class Momentum:
    def __init__(self):
        self.closes = []

    def on_bar(self, ctx, bar):
        self.closes.append(bar.close)
        if len(self.closes) &gt; 20:
            ctx.target(bar.symbol, 200 if bar.close &gt; self.closes[-21] else 0)


result = pyatl.backtest(
    Momentum(), {"005930": frame}, commission=0.00015, sell_tax=0.002
)
